.quiz-header { padding: 42px 46px 32px; background: linear-gradient(120deg, #273a85, #5266c5); color: white; }
.eyebrow { font-size: 11px; font-weight: 800; letter-spacing: .18em; opacity: .72; }
h1 { margin: 10px 0 8px; font-size: clamp(30px, 5vw, 44px); letter-spacing: -.04em; }
.quiz-header p { margin: 0; max-width: 540px; color: #dbe2ff; line-height: 1.6; font-size: 15px; }
.question-list { padding: 10px 46px 4px; }
.question { border: 0; border-bottom: 1px solid #e7eaf3; padding: 28px 0 30px; margin: 0; min-width: 0; }
.question:last-child { border-bottom: 0; }
legend { display: flex; gap: 15px; align-items: flex-start; padding: 0; width: 100%; font-size: 17px; font-weight: 750; line-height: 1.4; }
.question-number { color: #6679d2; font-size: 12px; letter-spacing: .1em; padding-top: 4px; }
.options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 19px 0 0 40px; }
.option { display: flex; align-items: center; gap: 10px; min-height: 48px; padding: 11px 13px; border: 1px solid #dce1ed; border-radius: 11px; color: #4c5870; cursor: pointer; font-size: 14px; transition: .2s ease; }
.option:hover { border-color: #8492dc; background: #f5f6ff; transform: translateY(-1px); }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-mark { width: 17px; height: 17px; flex: 0 0 17px; border: 2px solid #b8c0d2; border-radius: 50%; position: relative; }
.option:has(input:checked) { border-color: #5368cb; background: #f1f3ff; color: #273a85; font-weight: 650; }
.option input:checked + .radio-mark { border-color: #5368cb; }
.option input:checked + .radio-mark:after { content: ""; position: absolute; inset: 3px; border-radius: 50%; background: #5368cb; }
.quiz-footer { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 24px 46px 30px; background: #fafbfe; }
.status { margin: 0; color: #c04a5c; font-size: 13px; min-height: 19px; }
button { border: 0; border-radius: 10px; padding: 14px 21px; background: #5368cb; color: white; font: inherit; font-size: 14px; font-weight: 750; cursor: pointer; box-shadow: 0 7px 16px rgba(83,104,203,.25); transition: .2s ease; }
button:hover { background: #3f54b2; transform: translateY(-1px); }
button span { margin-left: 10px; font-size: 18px; }
.result { display: flex; align-items: baseline; justify-content: center; gap: 5px; padding: 25px; background: #172347; color: white; }
.result-label { margin-right: 10px; color: #aebcf4; font-size: 11px; font-weight: 800; letter-spacing: .16em; }
.result strong { color: #fff; font-size: 34px; line-height: 1; }
.out-of { color: #aeb8d9; font-size: 16px; }
.page-note { color: #77819d; text-align: center; font-size: 12px; }
@media (max-width: 620px) { .page-shell { padding-top: 20px; width: min(100% - 18px, 800px); } .quiz-header, .question-list { padding-left: 24px; padding-right: 24px; } .quiz-footer { padding-left: 24px; padding-right: 24px; align-items: flex-start; flex-direction: column; } .options { grid-template-columns: 1fr; margin-left: 0; } }

application.javascript:
(() => {
  const form = document.getElementById('quiz-form');
  const scoreElement = document.querySelector('[data-testid="quiz-score"]');
  const status = document.getElementById('status');
  const answers = { q1: 'a', q2: 'c', q3: 'b' };

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const formData = new FormData(form);
    const unanswered = ['q1', 'q2', 'q3'].filter((name) => !formData.get(name));

    if (unanswered.length) {
      status.textContent = `Please answer ${unanswered.length === 1 ? 'the remaining question' : 'all three questions'} before submitting.`;
      scoreElement.textContent = '—';
      scoreElement.removeAttribute('data-score');
      return;
    }

    let score = 0;
    Object.entries(answers).forEach(([name, answer]) => {
      if (formData.get(name) === answer) score += 1;
    });
    scoreElement.textContent = String(score);
    scoreElement.setAttribute('data-score', String(score));
    status.textContent = score === 3 ? 'Perfect score — excellent work!' : 'Answers checked. You can change your choices and submit again.';
  });
})();

