  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const selections = questionNames.reduce((result, name) => {
      const selected = form.querySelector(`input[name="${name}"]:checked`);
      result[name] = selected ? selected.value : '';
      return result;
    }, {});
    const unanswered = questionNames.filter((name) => !selections[name]);

    if (unanswered.length > 0) {
